#!/usr/bin/env python3
"""Build the 286 TLS 1.3 product crypto modules into one LZ4 module pack.

Every payload is a descriptor-driven, fixed-origin ``S286MOD2`` image with an
exact-target correctness gate.  The pack answers the physical questions the
product controller must preserve:

* every uncompressed payload fits the authenticated 0x4230..0x7a00 overlay;
* all compressed payloads can be cached from a read-only floppy before TCP;
* the two width-7 P-256 tables are generated by the target and therefore are
  deliberately absent from the on-disk ECDSA payload.

The chosen codec is a single raw LZ4 block per payload.  The standard legacy
LZ4 wrapper is used only to obtain reproducible blocks from the host tool; its
eight-byte wrapper is stripped because the module directory already carries
the compressed and uncompressed lengths.
"""

from __future__ import annotations

import hashlib
import json
import shutil
import struct
import subprocess
import sys
from dataclasses import dataclass
from pathlib import Path


HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[2]
SPIKE = HERE.parent / "tls13-spike"
BUILD = ROOT / "build/ibm_pc_5150/crypto-bench"
FROZEN_INCLUDE = BUILD / "tls13-product-head-includes"
PACK = BUILD / "tls13-286-modules.bin"
REPORT = BUILD / "tls13-286-modules.json"
META_INCLUDE = BUILD / "tls13-286-pack-meta.inc"
LOADER = BUILD / "tls13-286-pack-loader.bin"
LOADER_SOURCE = (
    ROOT / "targets/ibm_pc_5150/boot/tls13/tls13_286_pack_loader.asm"
)
CORE_FILES = (
    "layout.inc",
    "data.inc",
    "chacha20.inc",
    "poly1305.inc",
    "sha256.inc",
    "p256.inc",
)

MAGIC = b"S286PK02"
VERSION = 2
PACK_HEADER_BYTES = 512
PACK_BYTES = 41 * 512
PACK_DIRECTORY_OFFSET = 20
OVERLAY_START = 0x4230
OVERLAY_END = 0x7A00
OVERLAY_BYTES = OVERLAY_END - OVERLAY_START
WIDTH7_TABLE_BYTES = 127 * 64
ENTRY = struct.Struct("<8sHHHHIHH")


@dataclass(frozen=True)
class Payload:
    name: str
    kind: int
    source: Path
    raw_path: Path
    trim_tail: int = 0
    prebuilt: bool = False
    product_callable: bool = False


def run(command: list[str], *, capture: bool = False) -> subprocess.CompletedProcess[bytes]:
    return subprocess.run(
        command,
        cwd=ROOT,
        check=True,
        capture_output=capture,
    )


def materialize_source_core() -> tuple[str, str, bool]:
    """Freeze and identify the current core source used by this pack build."""
    commit = run(["git", "rev-parse", "HEAD"], capture=True).stdout.decode().strip()
    core_dir = FROZEN_INCLUDE / "core"
    core_dir.mkdir(parents=True, exist_ok=True)
    digest = hashlib.sha256()
    source_paths: list[str] = []
    for name in CORE_FILES:
        relative = f"targets/ibm_pc_5150/boot/core/{name}"
        contents = (ROOT / relative).read_bytes()
        (core_dir / name).write_bytes(contents)
        digest.update(name.encode("ascii"))
        digest.update(b"\0")
        digest.update(contents)
        source_paths.append(relative)
    dirty = bool(
        run(
            ["git", "status", "--porcelain", "--", *source_paths],
            capture=True,
        ).stdout
    )
    return commit, digest.hexdigest(), dirty


def assemble(source: Path, output: Path) -> bytes:
    run(
        [
            "nasm",
            "-f",
            "bin",
            f"-I{FROZEN_INCLUDE.resolve()}/",
            "-Itargets/ibm_pc_5150/boot/",
            "-Itools/crypto-bench/",
            "-o",
            str(output),
            str(source),
        ]
    )
    return output.read_bytes()


def crc16_ccitt(data: bytes) -> int:
    crc = 0xFFFF
    for byte in data:
        crc ^= byte << 8
        for _ in range(8):
            crc = ((crc << 1) ^ 0x1021) & 0xFFFF if crc & 0x8000 else crc << 1
    return crc


def compress_raw_lz4(raw_path: Path, raw: bytes) -> tuple[bytes, Path]:
    if shutil.which("lz4") is None:
        raise SystemExit("lz4 command is required to build the 286 module pack")
    legacy = raw_path.with_suffix(raw_path.suffix + ".legacy.lz4")
    decoded = raw_path.with_suffix(raw_path.suffix + ".roundtrip")
    run(["lz4", "-q", "-l", "-9", "-f", str(raw_path), str(legacy)])
    wrapped = legacy.read_bytes()
    if len(wrapped) < 8 or wrapped[:4] != b"\x02\x21\x4c\x18":
        raise AssertionError("lz4 did not emit the expected legacy frame")
    block_len = int.from_bytes(wrapped[4:8], "little")
    block = wrapped[8:]
    if block_len != len(block):
        raise AssertionError(
            f"expected one legacy LZ4 block ({block_len}), got {len(block)} bytes"
        )
    run(["lz4", "-q", "-d", "-f", str(legacy), str(decoded)])
    if decoded.read_bytes() != raw:
        raise AssertionError("LZ4 host round trip changed the module")
    block_path = raw_path.with_suffix(raw_path.suffix + ".lz4-block")
    block_path.write_bytes(block)
    return block, block_path


def main() -> None:
    BUILD.mkdir(parents=True, exist_ok=True)
    commit, source_snapshot_sha256, source_snapshot_dirty = (
        materialize_source_core()
    )
    run([sys.executable, str(HERE / "build_x25519_unrolled.py")])
    run([sys.executable, str(HERE / "build_x25519_product_module.py")])
    run([sys.executable, str(HERE / "build_mlkem_product_modules.py")])
    run([sys.executable, str(HERE / "build_ecdsa_product_module.py")])

    payloads = (
        Payload(
            "MLKEMKG",
            1,
            BUILD / "tls13-286-mlkem-keygen-module.bin",
            BUILD / "tls13-286-mlkem-keygen.raw",
            prebuilt=True,
            product_callable=True,
        ),
        Payload(
            "X25519",
            3,
            BUILD / "tls13-286-x25519-module.bin",
            BUILD / "tls13-286-x25519.raw",
            prebuilt=True,
            product_callable=True,
        ),
        Payload(
            "P256W7",
            4,
            ROOT / "targets/ibm_pc_5150/boot/tls13/p256_tablegen_286.asm",
            BUILD / "tls13-286-p256-tablegen.raw",
            product_callable=True,
        ),
        Payload(
            "MLKEM768",
            2,
            BUILD / "tls13-286-mlkem-decap-module.bin",
            BUILD / "tls13-286-mlkem.raw",
            prebuilt=True,
            product_callable=True,
        ),
        Payload(
            "ECDSAW7",
            5,
            BUILD / "tls13-286-ecdsa-module.bin",
            BUILD / "tls13-286-ecdsa-w7.raw",
            prebuilt=True,
            product_callable=True,
        ),
    )

    built: list[dict[str, object]] = []
    blocks: list[bytes] = []
    for payload in payloads:
        if payload.prebuilt:
            raw = payload.source.read_bytes()
            payload.raw_path.write_bytes(raw)
        else:
            raw = assemble(payload.source, payload.raw_path)
        if payload.trim_tail:
            if len(raw) <= payload.trim_tail:
                raise AssertionError("ECDSA image is smaller than its table tail")
            raw = raw[: -payload.trim_tail]
            payload.raw_path.write_bytes(raw)
        if len(raw) > OVERLAY_BYTES:
            raise AssertionError(
                f"{payload.name} is {len(raw)} bytes, overlay is {OVERLAY_BYTES}"
            )
        block, block_path = compress_raw_lz4(payload.raw_path, raw)
        blocks.append(block)
        built.append(
            {
                "name": payload.name,
                "kind": payload.kind,
                "source": str(payload.source.relative_to(ROOT)),
                "raw_path": str(payload.raw_path.relative_to(ROOT)),
                "raw_bytes": len(raw),
                "raw_sha256": hashlib.sha256(raw).hexdigest(),
                "crc16_ccitt": f"{crc16_ccitt(raw):04X}",
                "compressed_path": str(block_path.relative_to(ROOT)),
                "compressed_bytes": len(block),
                "overlay_start": OVERLAY_START,
                "overlay_end": OVERLAY_START + len(raw),
                "overlay_headroom": OVERLAY_BYTES - len(raw),
                "product_callable": payload.product_callable,
            }
        )

    directory_bytes = PACK_DIRECTORY_OFFSET + len(built) * ENTRY.size
    if directory_bytes > PACK_HEADER_BYTES:
        raise AssertionError("module directory no longer fits its header sector")
    offset = PACK_HEADER_BYTES
    entries = bytearray()
    for item, block in zip(built, blocks, strict=True):
        item["pack_offset"] = offset
        # Unknown flags fail closed in the product-v2 ABI.  Clear the research
        # bit only for fixed-origin S286MOD2 images that passed their callable
        # descriptor/KAT gate.
        flags = 1 | (0 if item["product_callable"] else 0x8000)
        entries += ENTRY.pack(
            str(item["name"]).encode("ascii").ljust(8, b"\0"),
            int(item["kind"]),
            flags,
            int(item["raw_bytes"]),
            len(block),
            offset,
            int(str(item["crc16_ccitt"]), 16),
            0,
        )
        offset += len(block)

    payload_end = offset
    if payload_end > PACK_BYTES:
        raise AssertionError(
            f"module payload ends at {payload_end}, beyond fixed "
            f"{PACK_BYTES}-byte cache"
        )
    # Keep the authenticated runtime/cache ABI fixed even when product-module
    # compression improves.  The loader validates every payload extent and
    # requires the unused suffix to remain zero, so this is deterministic
    # capacity padding rather than another executable surface.
    image_bytes = PACK_BYTES
    header = bytearray(PACK_HEADER_BYTES)
    struct.pack_into(
        "<8sHHHHI",
        header,
        0,
        MAGIC,
        VERSION,
        len(built),
        PACK_HEADER_BYTES,
        ENTRY.size,
        image_bytes,
    )
    header[PACK_DIRECTORY_OFFSET : PACK_DIRECTORY_OFFSET + len(entries)] = entries
    image = bytes(header) + b"".join(blocks)
    image += bytes(PACK_BYTES - len(image))
    PACK.write_bytes(image)
    loader = assemble(LOADER_SOURCE, LOADER)
    if len(loader) > OVERLAY_START - 0x3400:
        raise AssertionError("286 pack loader overlaps the module overlay")

    item_by_name = {str(item["name"]): item for item in built}
    META_INCLUDE.write_text(
        "".join(
            (
                f"{prefix}_raw_len equ {item_by_name[name]['raw_bytes']}\n"
                f"{prefix}_crc equ 0x{item_by_name[name]['crc16_ccitt']}\n"
            )
            for prefix, name in (
                ("kg", "MLKEMKG"),
                ("x", "X25519"),
                ("w7", "P256W7"),
                ("m", "MLKEM768"),
                ("e", "ECDSAW7"),
            )
        )
    )

    raw_total = sum(int(item["raw_bytes"]) for item in built)
    compressed_total = sum(int(item["compressed_bytes"]) for item in built)
    report = {
        "source_commit": commit,
        "source_snapshot_sha256": source_snapshot_sha256,
        "source_snapshot_dirty": source_snapshot_dirty,
        "format": {
            "magic": MAGIC.decode(),
            "version": VERSION,
            "header_bytes": PACK_HEADER_BYTES,
            "entry_bytes": ENTRY.size,
            "codec": "raw LZ4 block",
            "directory_offset": PACK_DIRECTORY_OFFSET,
            "payload_class": (
                "descriptor-driven fixed-origin S286MOD2 product modules; "
                "every entry clears the fail-closed research bit"
            ),
        },
        "overlay": {
            "start": OVERLAY_START,
            "end": OVERLAY_END,
            "bytes": OVERLAY_BYTES,
        },
        "payloads": built,
        "width7_tables": {
            "on_disk": False,
            "bases_live_in_race": 2,
            "bytes_per_base": WIDTH7_TABLE_BYTES,
            "target_generated_ram_bytes": 2 * WIDTH7_TABLE_BYTES,
        },
        "pre_tcp_modules": [
            "MLKEMKG",
            "P256W7",
            "MLKEM768",
        ],
        "critical_window_modules": [
            "X25519",
            "MLKEM768",
            "ECDSAW7",
        ],
        "raw_total_bytes": raw_total,
        "compressed_payload_bytes": compressed_total,
        "payload_end": payload_end,
        "zero_padding_bytes": PACK_BYTES - payload_end,
        "pack_bytes": len(image),
        "pack_sectors": len(image) // 512,
        "compression_ratio": compressed_total / raw_total,
        "pack_sha256": hashlib.sha256(image).hexdigest(),
        "loader": {
            "source": str(LOADER_SOURCE.relative_to(ROOT)),
            "image": str(LOADER.relative_to(ROOT)),
            "load_address": 0x3400,
            "bytes": len(loader),
            "sha256": hashlib.sha256(loader).hexdigest(),
        },
    }
    REPORT.write_text(json.dumps(report, indent=2, sort_keys=True) + "\n")
    print(json.dumps(report, indent=2, sort_keys=True))


if __name__ == "__main__":
    main()
